from collections import defaultdict

class Solution:
    def findWeightedMedian(self, n: int, edges: List[List[int]], weights: List[int], queries: List[List[int]]) -> List[int]:
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        def get_path(start: int, target: int) -> List[int]:
            parent = {start: None}
            queue = [start]
            visited = {start}
            for u in queue:
                if u == target:
                    break
                for v in adj[u]:
                    if v not in visited:
                        visited.add(v)
                        parent[v] = u
                        queue.append(v)
            path = []
            curr = target
            while curr is not None:
                path.append(curr)
                curr = parent[curr]
            return path[::-1]

