#include <vector>
#include <queue>
#include <algorithm>

class Solution {
public:
    std::vector<int> findWeightedMedian(int n, std::vector<std::vector<int>>& edges, std::vector<int>& weights, std::vector<std::vector<int>>& queries) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        std::vector<int> ans;
        ans.reserve(queries.size());

        for (const auto& q : queries) {
            int start = q[0], target = q[1];
            std::vector<int> parent(n, -2);
            parent[start] = -1;
            std::queue<int> qu;
            qu.push(start);

            while (!qu.empty()) {
                int u = qu.front();
                qu.pop();
                if (u == target) break;
                for (int v : adj[u]) {
                    if (parent[v] == -2) {
                        parent[v] = u;
                        qu.push(v);
                    }
                }
            }

            std::vector<int> path;
            int curr = target;
            while (curr != -1) {
                path.push_back(curr);
                curr = parent[curr];
            }
            std::reverse(path.begin(), path.end());

            long long total_weight = 0;
            for (int node : path) total_weight += weights[node];
            long long half = (total_weight + 1) / 2;

            long long running = 0;
            int median_node = path.back();
            for (int node : path) {
                running += weights[node];
                if (running >= half) {
                    median_node = node;
                    break;
                }
            }
            ans.push_back(median_node);
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] findWeightedMedian(int n, int[][] edges, int[] weights, int[][] queries) {
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] ans = new int[queries.length];
        for (int qIdx = 0; qIdx < queries.length; qIdx++) {
            int start = queries[qIdx][0], target = queries[qIdx][1];
            int[] parent = new int[n];
            Arrays.fill(parent, -2);
            parent[start] = -1;

            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(start);

            while (!queue.isEmpty()) {
                int u = queue.poll();
                if (u == target) break;
                for (int v : adj.get(u)) {
                    if (parent[v] == -2) {
                        parent[v] = u;
                        queue.add(v);
                    }
                }
            }

            List<Integer> path = new ArrayList<>();
            int curr = target;
            while (curr != -1) {
                path.add(curr);
                curr = parent[curr];
            }
            Collections.reverse(path);

            long totalWeight = 0;
            for (int node : path) totalWeight += weights[node];
            long half = (totalWeight + 1) / 2;

            long running = 0;
            int medianNode = path.get(path.size() - 1);
            for (int node : path) {
                running += weights[node];
                if (running >= half) {
                    medianNode = node;
                    break;
                }
            }
            ans[qIdx] = medianNode;
        }

        return ans;
    }
}

