var findWeightedMedian = function(n, edges, weights, queries) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const ans = [];
    for (const [start, target] of queries) {
        const parent = new Int32Array(n).fill(-2);
        parent[start] = -1;
        const queue = [start];

        let head = 0;
        while (head < queue.length) {
            const u = queue[head++];
            if (u === target) break;
            for (const v of adj[u]) {
                if (parent[v] === -2) {
                    parent[v] = u;
                    queue.push(v);
                }
            }
        }

        const path = [];
        let curr = target;
        while (curr !== -1) {
            path.push(curr);
            curr = parent[curr];
        }
        path.reverse();

        let totalWeight = 0;
        for (const node of path) totalWeight += weights[node];
        const half = Math.floor((totalWeight + 1) / 2);

        let running = 0;
        let medianNode = path[path.length - 1];
        for (const node of path) {
            running += weights[node];
            if (running >= half) {
                medianNode = node;
                break;
            }
        }
        ans.push(medianNode);
    }

    return ans;
};
